const characterInput={held:[false,false],lastLane:1,airUntil:0,autoReleaseAt:[0,0]};
function resetCharacterInput(){document.querySelectorAll('.is-down').forEach(el=>el.classList.remove('is-down'));characterInput.held=[false,false];characterInput.lastLane=1;characterInput.airUntil=0;characterInput.autoReleaseAt=[0,0];if(typeof visualMotion!=='undefined'){visualMotion.y=472;visualMotion.vy=0;visualMotion.squash=0;visualMotion.vs=0;}}
