function ensureContext(){if(!ctx){ctx=new (window.AudioContext||window.webkitAudioContext)({latencyHint:'interactive'});musicGain=ctx.createGain();sfxGain=ctx.createGain();mixGain=ctx.createGain();recordAudio=ctx.createMediaStreamDestination();musicGain.connect(mixGain);sfxGain.connect(mixGain);sfxGain.gain.value=settings.sfxVolume/100;mixGain.connect(ctx.destination);mixGain.connect(recordAudio);musicGain.gain.value=settings.volume/100;reactions=new SevenReactions.AudioReactions(ctx,musicGain,mixGain,sfxGain,()=>settings);}return ctx;}
