function clickTone(lane=0,when=null,cal=false,grade='PERFECT'){if(!ctx||(!cal&&(!settings.hitSound||settings.sfxVolume<=0)))return;const at=when??ctx.currentTime,bus=cal?mixGain:sfxGain;for(let i=0;i<(cal?1:2);i++){const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=cal?'sine':i?'sine':'triangle';const freq=cal?1000:grade==='GOOD'?(lane?540:720):(lane?760:1040);osc.frequency.setValueAtTime(freq*(i?1.5:1),at);osc.frequency.exponentialRampToValueAtTime(freq*(i?.7:.45),at+.065);gain.gain.setValueAtTime(cal?.16:i?.065:.11,at);gain.gain.exponentialRampToValueAtTime(.0001,at+.085);osc.connect(gain);gain.connect(bus);osc.start(at);osc.stop(at+.09);osc.onended=()=>{osc.disconnect();gain.disconnect();};}}
