function finishGame(){if(status==='finished')return;stopClock();setStatus('finished');reactions.stop();const outcome=SevenReactions.outcome(engine.counts,chart.notes.length,{practice,auto:engine.auto}),acc=engine.accuracy,rank=acc>=98?'S':acc>=90?'A':acc>=75?'B':'C',voiceKey=outcome.judged?SevenReactions.chooseVoice(outcome.hitRate):null;ending={...outcome,born:performance.now(),voiceKey};const celebration=outcome.fullCombo?reactions.celebrate():0,speech=voiceKey?reactions.play(voiceKey,outcome.fullCombo?.65:0):0;ending.until=ending.born+Math.max(outcome.fullCombo?5500:1200,celebration*1000,speech*1000+350);const friend=outcome.fullCombo||outcome.hitRate>80?'cheer':outcome.hitRate>=60?'tea':'shrug';$('result').innerHTML=`<div class="overlay-card result-card ${outcome.fullCombo?'is-full-combo':''}"><span class="eyebrow">${engine.auto?'AUTO PLAY · 演示结果':practice?'PRACTICE · 练习结果':'TRACK COMPLETE · 完成'}</span>${outcome.fullCombo?'<h2 class="full-combo-title">FULL COMBO!</h2><p class="fc-subtitle">零失误通关！每一拍，都接住了 ♡</p>':`<div class="result-grade">${rank}</div>`}<img class="ui-friend result-friend" src="${imageURL(decorImages[friend])}" alt="" aria-hidden="true"><div class="result-score">${String(engine.score).padStart(7,'0')}</div><div class="result-stats"><span>${outcome.hitRate.toFixed(2)}%<small>命中率</small></span><span>${acc.toFixed(2)}%<small>准确率</small></span><span>${engine.maxCombo}<small>最高连击</small></span><span>${engine.counts.PERFECT} / ${engine.counts.GOOD} / ${engine.counts.MISS}<small>PERFECT / GOOD / MISS</small></span></div><div class="result-buttons"><button id="againResult" class="primary">再来一次 ↗</button><button id="editResult">调整谱面</button></div></div>`;$('result').classList.remove('hidden');$('againResult').onclick=()=>startGame(practiceStart);$('editResult').onclick=()=>switchView('editor');}
