function syncSong(){$('songTitle').textContent=chart.title;$('songArtist').textContent=chart.artist;$('noteTotal').textContent=chart.notes.filter(n=>n.type!=='dodge').length;$('gearTotal').textContent=chart.notes.filter(n=>n.type==='dodge').length;$('holdTotal').textContent=chart.notes.filter(n=>n.type==='hold').length;$('durationTotal').textContent=timeText(duration());const kind=chart.source?.kind;$('songTag').textContent=kind==='tutorial'?'TUTORIAL':kind==='original-kawaii'?'KAWAII BASS':kind==='video-reconstruction'?(chart.source.difficulty==='easy'?'EASY · 简单':'STANDARD · 标准'):'CHART';$('songSource').textContent=kind==='tutorial'?'60 秒 · 原创 120 BPM 配乐。逐步学习短按、长按、齿轮和交叉击打。':kind==='original-kawaii'?'120 秒 · 150 BPM · 350 节拍。主歌四分音符、高潮八分音符；随乐句切换配色。':kind==='video-reconstruction'?chart.source.difficulty==='easy'?`${chart.bpm} BPM · 简单模式：减少连打，长按与齿轮前后留白。沿用标准谱面的落点与乐句配色。`:`${chart.bpm} BPM · 标准模式。连续短按间隔整理，配色按乐句统一。`:'可按时间轴编辑节奏、图案和颜色，导出时保留设置。';const built=Object.entries(A.examples).find(([key,item])=>item.chart.audio===chart.audio&&item.chart.title===chart.title);$('builtinChart').value=built?built[0]:'';const base=built?.[0]?.replace(/_easy$/,'');$('difficultyBar').classList.toggle('hidden',!A.examples[base+'_easy']);document.querySelectorAll('[data-difficulty]').forEach(b=>{b.disabled=loadingExample;b.classList.toggle('selected',b.dataset.difficulty===(built?.[0]?.endsWith('_easy')?'easy':'standard'));b.setAttribute('aria-pressed',String(b.classList.contains('selected')));});document.querySelectorAll('[data-song]').forEach(b=>{const chosen=base===b.dataset.song;b.classList.toggle('selected',chosen);b.setAttribute('aria-pressed',String(chosen));});if(status==='ready'&&$('startOverlay'))$('startOverlay').firstChild.textContent=kind==='tutorial'?'开始教程 ':'开始游玩 ';}

