// Image rendering: a flood fill removes only white regions touching the edge of supplied default sprites.
function loadImage(url){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('贴图无法读取。'));im.src=url;});}
function cutWhite(im){const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(im,0,0);const d=x.getImageData(0,0,c.width,c.height),p=d.data,w=c.width,h=c.height,visited=new Uint8Array(w*h),q=new Int32Array(w*h);let head=0,tail=0;const add=i=>{if(i<0||i>=w*h||visited[i])return;visited[i]=1;const j=i*4;if(p[j]>233&&p[j+1]>233&&p[j+2]>233){q[tail++]=i;p[j+3]=0;}};for(let xx=0;xx<w;xx++){add(xx);add((h-1)*w+xx);}for(let y=0;y<h;y++){add(y*w);add(y*w+w-1);}while(head<tail){const i=q[head++];if(i%w)add(i-1);if(i%w<w-1)add(i+1);add(i-w);add(i+w);}x.putImageData(d,0,0);return c;}
const charDefaults={run:'run',upper:'upper',lower:'lower',hold:'dash',good:'lower',miss:'portrait',upslash:'upslash',downslash:'downslash'};
async function loadSkins(){const token=++skinLoadToken;const next={};await Promise.all([...Object.keys(charDefaults),...Object.keys(A.skins),'background'].map(async key=>{let url=customSkins[key]||(charDefaults[key]?A.characters[charDefaults[key]]:A.skins[key]);if(!url)return;const im=await loadImage(url);next[key]=!customSkins[key]&&charDefaults[key]&&key!=='miss'?cutWhite(im):im;}));if(token!==skinLoadToken)return;images=next;refreshSkinSlots();}
