window.SevenBeat={get chart(){return chart;},get engine(){return engine;},get status(){return status;},get ready(){return bootReady;},get settings(){return settings;},get characterLane(){return characterLane();},get characterPose(){return characterPose();},get crossPose(){return crossPose();},get lesson(){return currentLesson();},get visualMotion(){return {...visualMotion};},get comboShining(){return comboShining();},get recording(){return recording;},get menuMusic(){return {playing:menuMusic.playing,key:menuMusic.key,enabled:menuMusic.enabled,blocked:menuMusic.blocked,allowed:menuMusic.allowed,time:menuMusic.audio.currentTime};},get noteAppearance(){return n=>({color:SevenColors.color(n,settings),shape:SevenColors.shape(n,settings)});},get fontLoaded(){return document.fonts.check('16px SevenCute');},get ending(){return ending?{...ending}:null;},get voiceKey(){return reactions?.lastVoice;},get voicePlaying(){return !!reactions?.voice;},get voiceDurations(){return Object.fromEntries(Object.entries(reactions?.buffers||{}).map(([k,v])=>[k,v.duration]));},get audioDuration(){return duration();},get clockTime(){return clockTime();},startGame,pauseGame,resumeGame,exitGame,switchView,validateChart};
